create extension if not exists pgcrypto;

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text,
  email text,
  photo_url text,
  created_at timestamptz not null default now(),
  onboarding_completed boolean not null default false,
  company_name text,
  tax_id text,
  company_logo text,
  whatsapp_number text,
  whatsapp_template text,
  payment_info text,
  quote_color text not null default '#FF9F1C',
  address text,
  profession text,
  brand_name text,
  brand_tone text not null default 'comercial'
    check (brand_tone in ('formal', 'técnico', 'comercial', 'criativo')),
  active_plan text not null default 'free'
    check (active_plan in ('free', 'pro', 'business')),
  plan_period text not null default 'monthly'
