create table if not exists public.quotes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  quote_number text not null,
  client_name text not null,
  client_phone text not null,
  client_email text,
  client_company text,
  client_vehicle_or_service text,
  notes text,
  items jsonb not null default '[]'::jsonb,
  subtotal numeric(12,2) not null default 0 check (subtotal >= 0),
  discount_total numeric(12,2) not null default 0 check (discount_total >= 0),
  taxes numeric(12,2) not null default 0 check (taxes >= 0),
  total numeric(12,2) not null default 0 check (total >= 0),
  valid_value_days integer not null default 15 check (valid_value_days between 1 and 365),
  payment_instructions text,
  status text not null default 'draft'
    check (status in ('draft', 'sent', 'viewed', 'pending', 'approved', 'rejected', 'expired')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  sent_at timestamptz,
  viewed_at timestamptz,
  approved_at timestamptz,
  rejected_at timestamptz
);

create table if not exists public.clients (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  name text not null,
  phone text not null,
  company text,
  vehicle_or_service text,
  notes text,
